#!/usr/bin/env bash
#
# Acceptance tests for scripts/sync-agents.sh, the generator that turns the
# hand-edited shared/ tree into the committed kit content under
# agent/files/home.
#
# Every case builds its own fixture (a shared/ tree plus a kit with hand-owned
# files) in a fresh temp directory, runs the generator against it with --root,
# and asserts the exit class and the observable output: generated bytes, the
# file named in a diagnostic, or the kit left untouched. Full message text is
# not asserted.
#
# The generator runs under "$BASH", the interpreter running this suite, so
# `/bin/bash scripts/test-sync-agents.sh` exercises bash 3.2 on macOS.
#
# Usage: scripts/test-sync-agents.sh [filter]
#   filter: run only the cases whose name contains this substring
#           (group names: emit, reject, sync, check, determinism)

set -uo pipefail

cd "$(dirname "$0")/.."

GEN="$PWD/scripts/sync-agents.sh"
FILTER="${1:-}"

TEST_TMP="$(mktemp -d "${TMPDIR:-/tmp}/test-sync-agents.XXXXXX")"
trap 'rm -rf "$TEST_TMP"' EXIT

pass=0
fail=0
case_seq=0

KIT_HOME=agent/files/home

# Fixture sources, as printf %b strings. Two of them deliberately end without
# a newline: real sources do (ROLE.md, planner.md, two rules, two skills), and
# the generator must not add one.
SRC_ROLE='# Role\n\nCore text.\n'
SRC_DELEGATION='## Delegation mechanics (Claude Code)\n\nThe sub-agents are defined in `.claude/agents`.\n'
SRC_ALPHA='---\nname: jarvis-alpha\ndescription: Alpha agent \xe2\x80\x94 does a, b: c.\nclaude.model: sonnet\n---\n\n# Alpha\n\nBody.\n'
SRC_BETA='---\nname: jarvis-beta\ndescription: Beta agent.\nrules: [plain]\nclaude.skills: ["a:b"]\n---\n\n# Beta\n\nBody without a trailing newline.'
SRC_RULE_PLAIN='# Plain\n\nRule text.\n'
SRC_RULE_SCOPED='---\npaths:\n  - "**/*.go"\n---\n\n# Scoped\n\nGo rule.'
SRC_SKILL="---\nname: demo\ndescription: 'Demo skill.'\n---\n\nSkill body."
SRC_SKILL_REF='reference notes\n'

# Hand-owned kit files: never read or written by the generator.
HAND_SPEC='name: fixture\n'
HAND_ROLE_LABEL='ENGINEER\n'
HAND_SETTINGS='{"model": "opus"}\n'
HAND_WORKFLOW='export default {};\n'

# marker_text <source description> -- the generated-file marker, no newline.
marker_text() {
	printf '<!-- GENERATED by scripts/sync-agents.sh from shared/%s -- edit that file, not this one -->' "$1"
}

# put <file> <printf-%b content> -- write a file, creating its directory.
put() {
	mkdir -p "$(dirname "$1")"
	printf '%b' "$2" >"$1"
}

# make_fixture <dir>
make_fixture() {
	local fx="$1"
	put "$fx/shared/role/ROLE.md" "$SRC_ROLE"
	put "$fx/shared/role/delegation.claude.md" "$SRC_DELEGATION"
	put "$fx/shared/agents/alpha.md" "$SRC_ALPHA"
	put "$fx/shared/agents/beta.md" "$SRC_BETA"
	put "$fx/shared/rules/plain.md" "$SRC_RULE_PLAIN"
	put "$fx/shared/rules/scoped.md" "$SRC_RULE_SCOPED"
	put "$fx/shared/skills/demo/SKILL.md" "$SRC_SKILL"
	put "$fx/shared/skills/demo/ref/notes.txt" "$SRC_SKILL_REF"
	put "$fx/agent/spec.yaml" "$HAND_SPEC"
	put "$fx/$KIT_HOME/.jarvis-role" "$HAND_ROLE_LABEL"
	put "$fx/$KIT_HOME/.claude/settings.json" "$HAND_SETTINGS"
	put "$fx/$KIT_HOME/.claude/workflows/x.js" "$HAND_WORKFLOW"
}

# gen <fixture> [args...] -- run the generator; sets $out (stdout+stderr), $rc.
gen() {
	local fx="$1"
	shift
	out="$("$BASH" "$GEN" --root "$fx" "$@" 2>&1)"
	rc=$?
}

# tree_sum <dir> -- one checksum line per file, path-sorted; content only.
tree_sum() {
	(cd "$1" && find . -type f | LC_ALL=C sort | while IFS= read -r f; do
		printf '%s %s\n' "$(cksum <"$f")" "$f"
	done)
}

# ---- assertion helpers: return 0 on success, print the reason otherwise ----

expect_rc() {
	if [[ "$rc" -ne "$1" ]]; then
		printf 'exit %s, want %s; output: %s' "$rc" "$1" "${out:-<empty>}"
		return 1
	fi
}

expect_output_names() {
	if [[ "$out" != *"$1"* ]]; then
		printf 'output does not name %s; output: %s' "$1" "${out:-<empty>}"
		return 1
	fi
}

# expect_bytes <actual file> <printf-%b expected content>
expect_bytes() {
	local want="$TEST_TMP/want.$$"
	printf '%b' "$2" >"$want"
	if [[ ! -f "$1" ]]; then
		printf 'missing file %s' "$1"
		return 1
	fi
	if ! cmp -s "$want" "$1"; then
		printf 'bytes differ for %s:\n%s' "$1" "$(diff "$want" "$1")"
		return 1
	fi
}

# run_case <name> <function> [args...]
#
# Builds a fresh fixture and calls <function> <fixture> [args...]. The function
# prints a reason and returns non-zero on failure.
run_case() {
	local name="$1" fn="$2" fx reason
	shift 2
	[[ -n "$FILTER" && "$name" != *"$FILTER"* ]] && return 0

	case_seq=$((case_seq + 1))
	fx="$TEST_TMP/case-$case_seq"
	make_fixture "$fx"

	if reason="$("$fn" "$fx" "$@")"; then
		printf 'ok   %s\n' "$name"
		pass=$((pass + 1))
	else
		printf 'FAIL %s\n     %s\n' "$name" "$reason"
		fail=$((fail + 1))
	fi
}

# ---- case bodies ----

# generates <fixture> <kit-home-relative path> <printf-%b expected content>
generates() {
	gen "$1"
	expect_rc 0 || return 1
	expect_bytes "$1/$KIT_HOME/$2" "$3"
}

# generated_line <fixture> <kit-home-relative path> <line number> <expected line>
generated_line() {
	local got
	gen "$1"
	expect_rc 0 || return 1
	if [[ ! -f "$1/$KIT_HOME/$2" ]]; then
		printf 'missing file %s' "$2"
		return 1
	fi
	got="$(sed -n "$3p" "$1/$KIT_HOME/$2")"
	if [[ "$got" != "$4" ]]; then
		printf 'line %s of %s is %s, want %s' "$3" "$2" "${got:-<empty>}" "$4"
		return 1
	fi
}

no_rules_key_in_agents() {
	gen "$1"
	expect_rc 0 || return 1
	if grep -l '^rules:' "$1/$KIT_HOME/.claude/agents/"*.md; then
		printf 'a generated agent carries a rules: line'
		return 1
	fi
}

copies_skill_tree() {
	gen "$1"
	expect_rc 0 || return 1
	if ! diff -r "$1/shared/skills/demo" "$1/$KIT_HOME/.claude/skills/demo" >/dev/null 2>&1; then
		printf 'skill tree differs: %s' "$(diff -r "$1/shared/skills/demo" "$1/$KIT_HOME/.claude/skills/demo" 2>&1)"
		return 1
	fi
}

# rejects <fixture> <shared-relative source> <printf-%b content>
#
# Replaces one source file with invalid content; the generator must exit 2 and
# name that source in its diagnostic.
rejects() {
	put "$1/shared/$2" "$3"
	gen "$1"
	expect_rc 2 || return 1
	expect_output_names "shared/$2"
}

rejects_usage() {
	gen "$1" --no-such-option
	expect_rc 2
}

invalid_source_leaves_kit_unchanged() {
	local before after
	gen "$1"
	expect_rc 0 || return 1
	before="$(tree_sum "$1/agent")"
	put "$1/shared/agents/alpha.md" '---\nname: jarvis-alpha\ndescription: d\ncolor: red\n---\n'
	put "$1/shared/rules/plain.md" '# Plain, edited\n'
	gen "$1"
	expect_rc 2 || return 1
	after="$(tree_sum "$1/agent")"
	if [[ "$before" != "$after" ]]; then
		printf 'kit changed after a rejected run'
		return 1
	fi
}

second_run_is_a_no_op() {
	local first second
	gen "$1"
	expect_rc 0 || return 1
	first="$(tree_sum "$1/agent")"
	gen "$1"
	expect_rc 0 || return 1
	second="$(tree_sum "$1/agent")"
	if [[ "$first" != "$second" ]]; then
		printf 'second run changed the kit'
		return 1
	fi
}

removed_source_removes_output() {
	gen "$1"
	expect_rc 0 || return 1
	rm "$1/shared/agents/beta.md" "$1/shared/rules/scoped.md"
	gen "$1"
	expect_rc 0 || return 1
	local f
	for f in .claude/agents/beta.md .claude/rules/scoped.md; do
		if [[ -e "$1/$KIT_HOME/$f" ]]; then
			printf '%s survived the removal of its source' "$f"
			return 1
		fi
	done
}

hand_owned_untouched() {
	gen "$1"
	expect_rc 0 || return 1
	expect_bytes "$1/agent/spec.yaml" "$HAND_SPEC" &&
		expect_bytes "$1/$KIT_HOME/.jarvis-role" "$HAND_ROLE_LABEL" &&
		expect_bytes "$1/$KIT_HOME/.claude/settings.json" "$HAND_SETTINGS" &&
		expect_bytes "$1/$KIT_HOME/.claude/workflows/x.js" "$HAND_WORKFLOW"
}

check_passes_when_fresh() {
	gen "$1"
	expect_rc 0 || return 1
	gen "$1" --check
	expect_rc 0
}

# check_detects <fixture> <edit: append|extra|symlink|remove> <kit-home-relative path>
check_detects() {
	gen "$1"
	expect_rc 0 || return 1
	case "$2" in
	append) printf 'hand edit\n' >>"$1/$KIT_HOME/$3" ;;
	extra) put "$1/$KIT_HOME/$3" 'stray\n' ;;
	symlink) ln -s ../rules/plain.md "$1/$KIT_HOME/$3" ;;
	remove) rm -r "$1/$KIT_HOME/$3" ;;
	esac
	gen "$1" --check
	expect_rc 1 || return 1
	expect_output_names "$KIT_HOME/$3"
}

check_ignores_hand_owned() {
	gen "$1"
	expect_rc 0 || return 1
	printf 'edited\n' >>"$1/agent/spec.yaml"
	printf 'edited\n' >>"$1/$KIT_HOME/.jarvis-role"
	printf 'edited\n' >>"$1/$KIT_HOME/.claude/settings.json"
	printf 'edited\n' >>"$1/$KIT_HOME/.claude/workflows/x.js"
	put "$1/$KIT_HOME/.claude/workflows/new.js" 'new\n'
	gen "$1" --check
	expect_rc 0
}

check_is_read_only() {
	local scratch="$1/scratch-tmp" before after leftover
	mkdir -p "$scratch"
	gen "$1"
	expect_rc 0 || return 1
	printf 'hand edit\n' >>"$1/$KIT_HOME/.claude/rules/plain.md"
	before="$(tree_sum "$1/agent")"
	out="$(TMPDIR="$scratch" "$BASH" "$GEN" --root "$1" --check 2>&1)"
	rc=$?
	expect_rc 1 || return 1
	after="$(tree_sum "$1/agent")"
	if [[ "$before" != "$after" ]]; then
		printf -- '--check modified the kit'
		return 1
	fi
	leftover="$(ls -A "$scratch")"
	if [[ -n "$leftover" ]]; then
		printf -- '--check left temp entries behind: %s' "$leftover"
		return 1
	fi
}

same_output_across_locales() {
	local other="$1-other" a b
	make_fixture "$other"
	out="$(LC_ALL=C "$BASH" "$GEN" --root "$1" 2>&1)"
	rc=$?
	expect_rc 0 || return 1
	out="$(LC_ALL=en_US.UTF-8 "$BASH" "$GEN" --root "$other" 2>&1)"
	rc=$?
	expect_rc 0 || return 1
	a="$(tree_sum "$1/agent")"
	b="$(tree_sum "$other/agent")"
	if [[ "$a" != "$b" ]]; then
		printf 'output differs between LC_ALL=C and LC_ALL=en_US.UTF-8'
		return 1
	fi
}

# ---- the table ----

printf '== sync-agents acceptance ==\n'

run_case "emit: writes name/description unchanged and maps claude.model to model:" \
	generates .claude/agents/alpha.md \
	"---\nname: jarvis-alpha\ndescription: Alpha agent \xe2\x80\x94 does a, b: c.\nmodel: sonnet\n---\n$(marker_text agents/alpha.md)\n\n# Alpha\n\nBody.\n"
run_case "emit: passes list values through byte for byte" \
	generated_line .claude/agents/beta.md 4 'skills: ["a:b"]'
run_case "emit: drops the rules: key from Claude agent files" \
	no_rules_key_in_agents
run_case "emit: places the marker right after the closing fence" \
	generated_line .claude/agents/alpha.md 6 "$(marker_text agents/alpha.md)"
run_case "emit: places the marker on line 1 of a file with no frontmatter" \
	generated_line .claude/rules/plain.md 1 "$(marker_text rules/plain.md)"
run_case "emit: keeps a body without a trailing newline without one" \
	generates .claude/agents/beta.md \
	"---\nname: jarvis-beta\ndescription: Beta agent.\nskills: [\"a:b\"]\n---\n$(marker_text agents/beta.md)\n\n# Beta\n\nBody without a trailing newline."
run_case "emit: keeps a rule's nested frontmatter first and puts the marker after it" \
	generates .claude/rules/scoped.md \
	"---\npaths:\n  - \"**/*.go\"\n---\n$(marker_text rules/scoped.md)\n\n# Scoped\n\nGo rule."
run_case "emit: copies skill directories byte for byte, with no marker" \
	copies_skill_tree
run_case "emit: concatenates role core, one blank line, delegation.claude.md into ROLE.md" \
	generates ROLE.md \
	"$(marker_text 'role/ROLE.md + shared/role/delegation.claude.md')\n${SRC_ROLE}\n${SRC_DELEGATION}"

run_case "reject: unknown frontmatter key" \
	rejects agents/alpha.md '---\nname: jarvis-alpha\ndescription: d\ncolor: red\n---\n\nBody.\n'
run_case "reject: indented (nested) frontmatter line in an agent" \
	rejects agents/alpha.md '---\nname: jarvis-alpha\ndescription: d\n  claude.model: sonnet\n---\n\nBody.\n'
run_case "reject: block scalar | in an agent" \
	rejects agents/alpha.md '---\nname: jarvis-alpha\ndescription: |\n  multi\n---\n\nBody.\n'
run_case "reject: block scalar > in an agent" \
	rejects agents/alpha.md '---\nname: jarvis-alpha\ndescription: >\n  folded\n---\n\nBody.\n'
run_case "reject: agent frontmatter closed by a dash run" \
	rejects agents/alpha.md '---\nname: jarvis-alpha\ndescription: d\n----------\n\nBody.\n'
run_case "reject: rule frontmatter closed by a dash run" \
	rejects rules/scoped.md '---\npaths:\n  - "**/*.go"\n-----\n\nGo rule.\n'
run_case "reject: unclosed agent frontmatter" \
	rejects agents/alpha.md '---\nname: jarvis-alpha\ndescription: d\n\nBody.\n'
run_case "reject: agent without frontmatter" \
	rejects agents/alpha.md '# Alpha\n\nBody.\n'
run_case "reject: missing name" \
	rejects agents/alpha.md '---\ndescription: d\n---\n\nBody.\n'
run_case "reject: missing description" \
	rejects agents/alpha.md '---\nname: jarvis-alpha\n---\n\nBody.\n'
run_case "reject: duplicate key" \
	rejects agents/alpha.md '---\nname: jarvis-alpha\nname: jarvis-again\ndescription: d\n---\n\nBody.\n'
run_case "reject: empty value" \
	rejects agents/alpha.md '---\nname: jarvis-alpha\ndescription: d\nclaude.model:\n---\n\nBody.\n'
run_case "reject: rules: entry with no shared/rules/<name>.md" \
	rejects agents/beta.md '---\nname: jarvis-beta\ndescription: d\nrules: [plain, nope]\n---\n\nBody.\n'
run_case "reject: rules: entry that is not a bare name" \
	rejects agents/beta.md '---\nname: jarvis-beta\ndescription: d\nrules: ["plain"]\n---\n\nBody.\n'
run_case "reject: .claude/ in a neutral agent body" \
	rejects agents/alpha.md '---\nname: jarvis-alpha\ndescription: d\n---\n\nSee .claude/agents.\n'
run_case "reject: subagent_type in a neutral agent body" \
	rejects agents/alpha.md '---\nname: jarvis-alpha\ndescription: d\n---\n\nPass subagent_type here.\n'
run_case "reject: .claude/ in the neutral role core" \
	rejects role/ROLE.md '# Role\n\nAgents live in .claude/agents.\n'
run_case "reject: role core without a trailing newline" \
	rejects role/ROLE.md '# Role\n\nCore text.'
run_case "reject: delegation fragment without a trailing newline" \
	rejects role/delegation.claude.md '## Delegation\n\nText.'
run_case "reject: skill with a key outside name, description" \
	rejects skills/demo/SKILL.md "---\nname: demo\ndescription: 'Demo.'\nmodel: sonnet\n---\n\nSkill body.\n"
run_case "reject: unknown option is a usage error" \
	rejects_usage
run_case "reject: invalid source leaves the kit directory unchanged" \
	invalid_source_leaves_kit_unchanged

run_case "sync: a second run changes nothing" \
	second_run_is_a_no_op
run_case "sync: a removed source removes its generated file" \
	removed_source_removes_output
run_case "sync: hand-owned paths are untouched" \
	hand_owned_untouched

run_case "check: passes on a freshly generated kit" \
	check_passes_when_fresh
run_case "check: fails and names a hand-edited generated file" \
	check_detects append .claude/rules/plain.md
run_case "check: fails and names a hand-edited ROLE.md" \
	check_detects append ROLE.md
run_case "check: fails and names an extra file in an owned subtree" \
	check_detects extra .claude/agents/extra.md
run_case "check: fails and names an extra symlink in an owned subtree" \
	check_detects symlink .claude/agents/stray.md
run_case "check: fails and names a missing file in an owned subtree" \
	check_detects remove .claude/rules/plain.md
run_case "check: fails and names a missing owned subtree" \
	check_detects remove .claude/skills
run_case "check: passes when only hand-owned files differ" \
	check_ignores_hand_owned
run_case "check: does not modify the kit and leaves no temp directory behind" \
	check_is_read_only

run_case "determinism: identical output under LC_ALL=C and LC_ALL=en_US.UTF-8" \
	same_output_across_locales

printf '\n%d passed, %d failed\n' "$pass" "$fail"
[[ $fail -eq 0 && $pass -gt 0 ]]
